package io.github.mekkiamiri.ratchet.order.web;

import io.github.mekkiamiri.ratchet.order.domain.Order;
import java.math.BigDecimal;
import java.text.SimpleDateFormat;
import java.util.Date;

/** createdAt (java.util.Date) et createdAtLabel sont exigés par le SDK client Java 6. */
public record OrderResponse(String id, String customer, String status, BigDecimal total, Date createdAt,
        String createdAtLabel) {

    static OrderResponse from(Order order) {
        Date createdAt = Date.from(order.createdAt());
        // SimpleDateFormat n'est pas thread-safe : une instance par appel.
        String label = new SimpleDateFormat("dd/MM/yyyy HH:mm").format(createdAt);
        return new OrderResponse(order.id().value(), order.customer(), order.status().name(), order.total(),
                createdAt, label);
    }
}
